args.command:
cat > /tmp/probe/theme.toml <<'EOF'
[process]
name = { fg = "red", bold = true }
pid = { fg = "blue", italic = true }
brackets = { fg = "green", underline = true }
EOF
printf 'systemd[1]: x\n' | /workspace/executable --enable processes --disable-builtin-keywords --config-path /tmp/probe/theme.toml | cat -v; echo EXIT=$?
